package org.tubalabs.products;

import com.azure.core.util.BinaryData;
import com.azure.storage.blob.BlobContainerClient;
import com.azure.storage.blob.models.BlobHttpHeaders;
import com.azure.storage.blob.options.BlobParallelUploadOptions;
import org.springframework.context.annotation.Profile;
import org.springframework.http.*;
import org.springframework.security.web.csrf.CsrfToken;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.server.ResponseStatusException;

import java.nio.ByteBuffer;
import java.nio.charset.*;
import java.security.MessageDigest;
import java.util.*;

@Controller @Profile("!inspect")
class ProductsController {
    private final Store store;
    private final BlobContainerClient blobs;
    ProductsController(Store store, BlobContainerClient blobs) { this.store = store; this.blobs = blobs; }
    @GetMapping("/") String uploadPage(Model model) { model.addAttribute("products", store.products()); return "upload"; }
    @GetMapping("/chat") String chatPage(Model model) { model.addAttribute("products", store.products()); return "chat"; }
    @GetMapping("/api/csrf") @ResponseBody Map<String,String> csrf(CsrfToken token) {
        return Map.of("token", token.getToken(), "headerName", token.getHeaderName());
    }
    @GetMapping("/api/products") @ResponseBody Object products() { return store.products(); }
    @GetMapping("/api/products/{id}") @ResponseBody Object product(@PathVariable UUID id) {
        return store.product(id).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND));
    }
    @PostMapping(value="/api/products", consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @ResponseBody
    ResponseEntity<Store.Product> uploadApi(@RequestParam String name, @RequestParam MultipartFile manual) throws Exception {
        return ResponseEntity.status(201).body(upload(name, manual));
    }
    @PostMapping(value="/products", consumes=MediaType.MULTIPART_FORM_DATA_VALUE)
    String uploadForm(@RequestParam String name, @RequestParam MultipartFile manual) throws Exception {
        upload(name, manual); return "redirect:/";
    }
    private Store.Product upload(String name, MultipartFile manual) throws Exception {
        String filename = Objects.toString(manual.getOriginalFilename(), "");
        if (name == null || name.isBlank() || name.length() > 120 || !filename.endsWith(".txt") || manual.isEmpty() || manual.getSize() > 131072)
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Use a name (1..120 characters) and a UTF-8 .txt manual up to 128 KiB");
        byte[] data = manual.getBytes();
        try {
            String text = StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(data)).toString();
            if (text.isBlank() || text.indexOf('\0') >= 0) throw new CharacterCodingException();
        } catch (CharacterCodingException error) { throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Manual must contain UTF-8 text without NUL bytes"); }
        String sha = HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data));
        Store.Product product = store.createProduct(name.strip(), sha);
        try {
            var options = new BlobParallelUploadOptions(BinaryData.fromBytes(data))
                    .setHeaders(new BlobHttpHeaders().setContentType("text/plain; charset=utf-8"))
                    .setMetadata(Map.of("productid", product.id().toString(), "manualid", product.manualId().toString(), "sha256", sha));
            // UUID paths are new and immutable. Refuse replacement explicitly.
            options.setRequestConditions(new com.azure.storage.blob.models.BlobRequestConditions().setIfNoneMatch("*"));
            blobs.getBlobClient(product.blobName()).uploadWithResponse(options, null, com.azure.core.util.Context.NONE);
            return product;
        } catch (Exception error) {
            store.failUpload(product.id());
            throw new ResponseStatusException(HttpStatus.BAD_GATEWAY, "Upload failed. Check Products status and server logs.");
        }
    }
    record Question(String question, UUID productId) {}
    @PostMapping(value="/api/questions", consumes=MediaType.APPLICATION_JSON_VALUE) @ResponseBody
    ResponseEntity<Store.Chat> ask(@RequestBody Question input) {
        if (input.question() == null || input.question().isBlank() || input.question().length() > 1000)
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Question must be 1..1000 characters");
        if (input.productId() != null && store.product(input.productId()).filter(p -> p.status().equals("ready")).isEmpty())
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Wait for the selected manual to be ready");
        return ResponseEntity.accepted().body(store.createQuestion(input.question().strip(), input.productId()));
    }
    @GetMapping("/api/questions/{id}") @ResponseBody Object question(@PathVariable UUID id) {
        store.expire();
        return store.chat(id).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND));
    }
    @ExceptionHandler(ResponseStatusException.class) @ResponseBody ResponseEntity<Map<String,String>> badRequest(ResponseStatusException error) {
        return ResponseEntity.status(error.getStatusCode()).body(Map.of("error", Objects.toString(error.getReason(), "Request failed")));
    }
}

package org.tubalabs.products;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.context.annotation.DependsOn;
import org.springframework.context.annotation.Profile;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;

import javax.sql.DataSource;
import java.time.OffsetDateTime;
import java.util.*;

@Repository @Profile("!inspect") @DependsOn("flyway")
public class Store {
    public record Product(UUID id, String name, UUID manualId, String status, String error, String blobName) {}
    public record Chat(UUID id, UUID correlationId, UUID productId, String question, String status,
                       String answer, List<Map<String,Object>> sources, String error, OffsetDateTime deadline) {}
    private final JdbcClient sql;
    private final TransactionTemplate transaction;
    private final ObjectMapper json = new ObjectMapper();
    public Store(JdbcClient sql, DataSource dataSource) {
        this.sql = sql; this.transaction = new TransactionTemplate(new DataSourceTransactionManager(dataSource));
    }
    public Product createProduct(String name, String sha256) {
        UUID id = UUID.randomUUID(), manual = UUID.randomUUID();
        String path = "products/" + id + "/" + manual + ".txt";
        // This statement commits before the controller starts the blob upload.
        sql.sql("INSERT INTO products(id,name,manual_id,blob_name,manual_sha256) VALUES (?,?,?,?,?)")
                .params(id, name, manual, path, sha256).update();
        return new Product(id, name, manual, "waiting", null, path);
    }
    public void failUpload(UUID id) {
        sql.sql("UPDATE products SET status='failed',error=?,updated_at=now() WHERE id=? AND status='waiting'")
                .params("Blob upload failed. Inspect Products logs; retry by creating a new product.", id).update();
    }
    public List<Product> products() {
        return sql.sql("SELECT id,name,manual_id,status,error,blob_name FROM products ORDER BY created_at DESC")
                .query((row, index) -> new Product(row.getObject(1, UUID.class), row.getString(2), row.getObject(3, UUID.class),
                        row.getString(4), row.getString(5), row.getString(6))).list();
    }
    public Optional<Product> product(UUID id) { return products().stream().filter(product -> product.id().equals(id)).findFirst(); }
    public Chat createQuestion(String question, UUID productId) {
        UUID id = UUID.randomUUID(), correlation = UUID.randomUUID();
        OffsetDateTime deadline = OffsetDateTime.now().plusMinutes(8);
        Map<String,Object> payload = new LinkedHashMap<>();
        payload.put("schemaVersion", 1); payload.put("type", "chat.request"); payload.put("requestId", id.toString());
        payload.put("correlationId", correlation.toString()); payload.put("productId", productId == null ? null : productId.toString());
        payload.put("question", question); payload.put("deadline", deadline.toString());
        transaction.executeWithoutResult(status -> {
            sql.sql("INSERT INTO chat_requests(id,correlation_id,product_id,question,deadline) VALUES (?,?,?,?,?)")
                    .param(id).param(correlation).param(productId).param(question).param(deadline).update();
            sql.sql("INSERT INTO chat_outbox(request_id,payload) VALUES (?,?::jsonb)").params(id, encode(payload)).update();
        });
        return chat(id).orElseThrow();
    }
    public List<Map<String,Object>> outgoing() {
        return sql.sql("SELECT o.request_id,o.payload::text FROM chat_outbox o JOIN chat_requests r ON r.id=o.request_id "
                + "WHERE o.sent_at IS NULL AND r.status='queued' AND r.deadline>now() ORDER BY r.created_at LIMIT 10")
                .query((row, i) -> Map.<String,Object>of("id", row.getObject(1, UUID.class), "payload", row.getString(2))).list();
    }
    public void sent(UUID id) { sql.sql("UPDATE chat_outbox SET sent_at=now(),attempts=attempts+1 WHERE request_id=?").param(id).update(); }
    public Optional<Chat> chat(UUID id) {
        return sql.sql("SELECT id,correlation_id,product_id,question,status,answer,sources::text,error,deadline FROM chat_requests WHERE id=?")
                .param(id).query((row, i) -> new Chat(row.getObject(1, UUID.class), row.getObject(2, UUID.class), row.getObject(3, UUID.class),
                        row.getString(4), row.getString(5), row.getString(6), decodeSources(row.getString(7)), row.getString(8),
                        row.getObject(9, OffsetDateTime.class))).optional();
    }
    public int applyReply(String payload, String correlationHeader) {
        try {
            var reply = json.readTree(payload);
            if (reply.path("schemaVersion").asInt() != 1 || !reply.path("type").asText().equals("chat.reply")
                    || !Set.of("completed", "failed").contains(reply.path("status").asText())
                    || !reply.path("sources").isArray() || !reply.path("answer").isTextual()
                    || !reply.path("correlationId").asText().equals(correlationHeader))
                throw new IllegalArgumentException("Invalid reply schema or correlation header");
            UUID id = UUID.fromString(reply.path("requestId").asText());
            UUID correlation = UUID.fromString(correlationHeader);
            return sql.sql("UPDATE chat_requests SET status=?,answer=?,sources=?::jsonb,error=?,updated_at=now() "
                    + "WHERE id=? AND correlation_id=? AND status IN ('queued','processing') AND deadline>now()")
                    .param(reply.path("status").asText()).param(reply.path("answer").asText()).param(reply.path("sources").toString())
                    .param(reply.path("errorCode").isNull() ? null : reply.path("errorCode").asText())
                    .param(id).param(correlation).update();
        } catch (JsonProcessingException error) { throw new IllegalArgumentException("Invalid reply JSON", error); }
    }
    public void expire() {
        sql.sql("UPDATE chat_requests SET status='failed',error='Request timed out after eight minutes. Check queue depth, worker logs and dead letters.',updated_at=now() "
                + "WHERE status IN ('queued','processing') AND deadline<=now()").update();
        sql.sql("UPDATE products SET status='failed',error='Indexing timed out. Check Event Grid delivery, Function logs and poison queue.',updated_at=now() "
                + "WHERE status IN ('waiting','processing') AND updated_at<now()-interval '12 minutes'").update();
    }
    public String encode(Object value) {
        try { return json.writeValueAsString(value); }
        catch (JsonProcessingException error) { throw new IllegalArgumentException("Cannot encode message", error); }
    }
    private List<Map<String,Object>> decodeSources(String value) {
        try { return json.readValue(value, json.getTypeFactory().constructCollectionType(List.class, Map.class)); }
        catch (JsonProcessingException error) { throw new IllegalArgumentException("Invalid sources", error); }
    }
}

'use strict';
const byId = id => document.getElementById(id);
async function api(path, options = {}) {
  const response = await fetch(path, options);
  if (!response.ok) throw new Error('Request failed (' + response.status + '). Check sign-in, CSRF token, and Products logs.');
  return response.json();
}
const productBody = byId('products-body');
if (productBody) {
  const update = async () => {
    try {
      const products = await api('/api/products');
      productBody.replaceChildren(...products.map(product => {
        const row = document.createElement('tr');
        for (const value of [product.name, product.status, product.error || '']) {
          const cell = document.createElement('td'); cell.textContent = value; row.append(cell);
        }
        return row;
      }));
      byId('products-status').textContent = '';
    } catch (error) { byId('products-status').textContent = error.message; }
  };
  setInterval(update, 3000);
}
const form = byId('chat-form');
if (form) {
  let pollTimer;
  function render(result) {
    byId('result').hidden = false;
    byId('request-state').textContent = result.status + (result.error ? ': ' + result.error : '');
    byId('answer').textContent = result.answer || 'Waiting for the asynchronous worker…';
    byId('request-id').textContent = 'Request ' + result.id + ' · correlation ' + result.correlationId;
    byId('sources').replaceChildren(...result.sources.map(source => {
      const item = document.createElement('li'), title = document.createElement('strong'), quote = document.createElement('blockquote');
      title.textContent = '[' + source.reference + '] ' + source.productName + ' · chunk ' + source.chunkIndex;
      quote.textContent = source.excerpt;
      const detail = document.createElement('small'); detail.textContent = 'Manual ' + source.manualId;
      item.append(title, quote, detail); return item;
    }));
  }
  async function poll(id, until = Date.now() + 9 * 60 * 1000) {
    clearTimeout(pollTimer);
    try {
      const result = await api('/api/questions/' + encodeURIComponent(id)); render(result);
      if (['queued', 'processing'].includes(result.status) && Date.now() < until) {
        pollTimer = setTimeout(() => poll(id, until), 2000);
      } else {
        byId('ask').disabled = false;
        if (Date.now() >= until) byId('request-state').textContent = 'Polling timed out. Refresh to read the persisted request status.';
      }
    } catch (error) { byId('request-state').textContent = error.message + ' Refresh to retry polling.'; byId('ask').disabled = false; }
  }
  form.addEventListener('submit', async event => {
    event.preventDefault(); byId('ask').disabled = true;
    try {
      const csrf = await api('/api/csrf');
      const result = await api('/api/questions', {method: 'POST', headers: {'Content-Type': 'application/json', [csrf.headerName]: csrf.token},
        body: JSON.stringify({question: byId('question').value, productId: byId('product').value || null})});
      const url = new URL(location.href); url.searchParams.set('request', result.id); history.replaceState(null, '', url);
      render(result); poll(result.id);
    } catch (error) { byId('result').hidden = false; byId('request-state').textContent = error.message; byId('ask').disabled = false; }
  });
  const request = new URLSearchParams(location.search).get('request');
  if (request && /^[0-9a-f-]{36}$/.test(request)) { byId('ask').disabled = true; poll(request); }
}

package org.tubalabs.products;

import com.azure.storage.blob.*;
import com.azure.storage.blob.options.BlobParallelUploadOptions;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.boot.autoconfigure.EnableAutoConfiguration;
import org.springframework.boot.builder.SpringApplicationBuilder;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.context.annotation.*;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.core.userdetails.*;
import org.springframework.security.provisioning.InMemoryUserDetailsManager;
import org.springframework.security.web.SecurityFilterChain;

import javax.sql.DataSource;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;

import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;

/** Real HTTP + PostgreSQL + security; ONLY Blob Storage is a deterministic boundary fixture. */
@EnabledIfEnvironmentVariable(named="TEST_DATABASE_URL", matches=".+")
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class HttpFlowTest {
    static final AtomicBoolean committedBeforeBlob = new AtomicBoolean();
    ConfigurableApplicationContext context;
    HttpClient browser;
    String endpoint;
    final ObjectMapper json = new ObjectMapper();
    @BeforeAll void start() {
        context = new SpringApplicationBuilder(Fixture.class).properties("server.port=0", "spring.main.banner-mode=off", "logging.level.root=WARN").run();
        endpoint = "http://127.0.0.1:" + context.getEnvironment().getProperty("local.server.port");
        browser = HttpClient.newBuilder().cookieHandler(new CookieManager(null, CookiePolicy.ACCEPT_ALL)).build();
    }
    @AfterAll void stop() { if (context != null) context.close(); }
    HttpRequest.Builder request(String path) {
        return HttpRequest.newBuilder(URI.create(endpoint + path)).header("Accept", "application/json")
                .header("Authorization", "Basic " + Base64.getEncoder().encodeToString("participant:local-test-only".getBytes(StandardCharsets.UTF_8)));
    }
    @Test void uploadAndChatUseRealHttpCsrfRecordsAndPersistentReplies() throws Exception {
        var denied = browser.send(request("/api/questions").header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString("{\"question\":\"fixture\",\"productId\":null}")).build(), HttpResponse.BodyHandlers.ofString());
        // A fresh request may receive an auth challenge before CSRF denial.
        // The authenticated token flow below must still succeed end to end.
        assertThat(denied.statusCode()).isIn(401, 403);
        var tokenResponse = browser.send(request("/api/csrf").GET().build(), HttpResponse.BodyHandlers.ofString());
        assertThat(tokenResponse.statusCode()).isEqualTo(200);
        var csrf = json.readTree(tokenResponse.body());
        String header = csrf.path("headerName").asText(), token = csrf.path("token").asText();
        String boundary = "WorkshopBoundary" + UUID.randomUUID().toString().replace("-", "");
        String body = "--" + boundary + "\r\nContent-Disposition: form-data; name=\"name\"\r\n\r\nHTTP fixture lamp\r\n"
                + "--" + boundary + "\r\nContent-Disposition: form-data; name=\"manual\"; filename=\"manual.txt\"\r\nContent-Type: text/plain\r\n\r\nA fictional lamp outputs 420 lumens.\r\n"
                + "--" + boundary + "--\r\n";
        var uploaded = browser.send(request("/api/products").header(header, token)
